def identify_trend(prices, moving_average=None, trendline=None):
    if moving_average is not None:
        prices = [p for p in prices if p > moving_average]
    if trendline is not None:
        prices = [p for p in prices if p > trendline]
    lows = [p for i, p in enumerate(prices) if all(prices[j] > p for j in range(i))]
    highs = [p for i, p in enumerate(prices) if all(prices[j] < p for j in range(i))]
    if len(lows) > 1 and all(lows[i] < lows[i+1] for i in range(len(lows)-1)):
        return 'uptrend'
    elif len(highs) > 1 and all(highs[i] > highs[i+1] for i in range(len(highs)-1)):
        return 'downtrend'
    else:
        return 'no trend'

