        return 'cold and gentle'
    elif wind_speed < 5 and temperature >= 15:
        return 'warm and gentle'
    elif wind_speed >= 5 and wind_speed < 10 and temperature < 15:
        return 'cold and breezy'
    elif wind_speed >= 5 and wind_speed < 10 and temperature >= 15:
        return 'warm and breezy'
    elif wind_speed >= 10 and temperature < 15:
        return 'cold and gusty'
    elif wind_speed >= 10 and temperature >= 15:
        return 'hot and muggy'
    else:
        return 'unknown'

