    # Simulate voting process
    for vote in votes:
        candidate_votes[vote] += 1

    # Calculate seats for each candidate
    candidate_seats = {}
    for candidate, vote_count in candidate_votes.items():
        seats = int((vote_count / len(votes)) * fa_seats)
        if seats > 0:
            candidate_seats[candidate] = seats

    # Distribute remaining seats to top candidates
    remaining_seats = fa_seats - sum(candidate_seats.values())
    for candidate in sorted(candidate_seats, key=candidate_seats.get, reverse=True):
