def is_valid_phrase(phrase, vowels, common_word_fragments, letter_distribution):
  # Remove non-alphabetic characters and convert to lowercase
  phrase = ''.join(filter(str.isalpha, phrase)).lower()

  # Initialize variables
  phrase_length = len(phrase)
  vowels_found = 0
  valid_word_fragments = 0

  # Check for vowels
  for char in phrase:
    if char in vowels:
      vowels_found += 1

  # Check for common word fragments
  for fragment in common_word_fragments:
    if fragment in phrase:
      valid_word_fragments += 1

  # Check letter distribution
  for char in phrase:
    if char in letter_distribution:
      letter_distribution[char] += 1

  # Calculate the ratio of vowels to total characters
  vowel_ratio = vowels_found / phrase_length

  # Calculate the ratio of valid word fragments to total characters
  fragment_ratio = valid_word_fragments / phrase_length

  # Determine if the phrase is valid based on the ratios
  if vowel_ratio > 0.2 and fragment_ratio > 0.1:
    return True
  else:
    return False

